  constructor() {
    this.clients = new Map();
    this.global = new BoundedQueue(100);
    this.workers = new WorkerPool(4);
  }

  enqueue(clientId, item) {
    let q = this.clients.get(clientId) ?? new Queue();
    q.enqueue(item);
    this.clients.set(clientId, q);
    if (!this.global.isFull()) {
      this.global.enqueue({ clientId, item: q.peek() });
    }
